	@Test
	void sharesOneLazyProducerAcrossOverlappingProbesAndSnapshotsMutableRows() {
		var context = new QueryEvaluationContext.Minimal(null);
		AtomicInteger opens = new AtomicInteger();
		AtomicInteger reads = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();
		QueryEvaluationStep producer = input -> {
			opens.incrementAndGet();
			return new LookAheadIteration<>() {
				private final QueryBindingSet reusable = new QueryBindingSet();

				@Override
				protected BindingSet getNextElement() {
					int index = reads.getAndIncrement();
					if (index == 3) {
						return null;
					}
					reusable.setBinding("key", VF.createLiteral(index % 2));
					reusable.setBinding("allocation", VF.createBNode());
					return reusable;
				}

				@Override
				protected void handleClose() {
					closes.incrementAndGet();
				}
			};
		};
		var plan = RestrictionCompiler.replay("test/replay", assignment(), context, producer,
				DefaultCollectionFactory::new);
		var layout = plan.layout();
		var narrow = layout.unrestricted().restrict(layout.slot("key"), VF.createLiteral(0));
		try (var invocation = plan.open(EMPTY, InvocationOwner.forExecution(context))) {
			assertThat(opens).hasValue(0);
			BindingSet first;
			try (var rows = invocation.probe(narrow)) {
				assertThat(rows.hasNext()).isTrue();
				first = rows.next();
				assertThatThrownBy(() -> invocation.probe(layout.unrestricted()))
						.isInstanceOf(IllegalStateException.class);
			}
			assertThat(reads).hasValue(1);
			assertThat(closes).hasValue(0);
			List<BindingSet> full = read(invocation.probe(layout.unrestricted()));
			assertThat(full).hasSize(3);
			assertThat(full.getFirst()).isEqualTo(first);
			assertThat(full.stream().map(row -> row.getValue("allocation"))).doesNotHaveDuplicates();
			assertThat(read(invocation.probe(narrow))).containsExactly(full.get(0), full.get(2));
			assertThat(opens).hasValue(1);
			assertThat(closes).hasValue(1);
			invocation.completeNormally();
			invocation.completeNormally();
			assertThatThrownBy(() -> invocation.probe(narrow)).isInstanceOf(IllegalStateException.class);
		}
		assertThat(closes).hasValue(1);
	}

	@Test
	void earlyCloseAndCancellationDoNotStartOrDrainReplay() {
		var context = new QueryEvaluationContext.Minimal(null);
		AtomicInteger opens = new AtomicInteger();
		AtomicInteger reads = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();
		BindingSet row = EMPTY;
		QueryEvaluationStep producer = input -> {
			opens.incrementAndGet();
			return new LookAheadIteration<>() {
				@Override
				protected BindingSet getNextElement() {
					if (reads.getAndIncrement() > 0) {
						throw new AssertionError("replay read past the demanded prefix");
					}
					return row;
				}

				@Override
				protected void handleClose() {
					closes.incrementAndGet();
				}
			};
		};
		var plan = RestrictionCompiler.replay("test/replay", assignment(), context, producer,
				DefaultCollectionFactory::new);
		plan.open(EMPTY, InvocationOwner.forExecution(context)).close();
		assertThat(opens).hasValue(0);

		try (var invocation = plan.open(EMPTY, InvocationOwner.forExecution(context));
				var rows = invocation.probe(plan.layout().unrestricted())) {
			assertThat(rows.next()).isEqualTo(row);
			invocation.requestCancellation();
		}
		assertThat(opens).hasValue(1);
		assertThat(reads).hasValue(1);
		assertThat(closes).hasValue(1);
	}

