	@Test
	void producerFailureClosesExactlyOnceAndCannotBeRetried() {
		var context = new QueryEvaluationContext.Minimal(null);
		AtomicInteger closes = new AtomicInteger();
		QueryEvaluationStep producer = input -> new LookAheadIteration<>() {
			@Override
			protected BindingSet getNextElement() {
				throw new IllegalStateException("producer failed");
			}

			@Override
			protected void handleClose() {
				closes.incrementAndGet();
				throw new IllegalArgumentException("producer close failed");
			}
		};
		var plan = RestrictionCompiler.replay("test/replay", assignment(), context, producer,
				DefaultCollectionFactory::new);
		var unrestricted = plan.layout().unrestricted();
		try (var invocation = plan.open(EMPTY, InvocationOwner.forExecution(context))) {
			try (var rows = invocation.probe(unrestricted)) {
				assertThatThrownBy(rows::hasNext).isInstanceOf(IllegalStateException.class)
						.hasMessage("producer failed")
						.satisfies(failure -> assertThat(failure.getSuppressed()).hasSize(1));
			}
			assertThatThrownBy(() -> invocation.probe(unrestricted)).isInstanceOf(IllegalStateException.class);
		}
		assertThat(closes).hasValue(1);
	}

	@Test
	void replayRetainsOriginalInputAndOutputOutsidePreparedArrayLayout() {
		var context = new ArrayBindingBasedQueryEvaluationContext(new QueryEvaluationContext.Minimal(null),
				new String[] { "key", "allocation" }, null);
		var input = new QueryBindingSet();
		input.setBinding("inputOnly", VF.createLiteral("original"));
		QueryEvaluationStep producer = beta -> {
			QueryBindingSet row = new QueryBindingSet(beta);
			row.setBinding("producerOnly", VF.createLiteral("extra"));
			return new SingletonIteration<>(row);
		};
		var plan = RestrictionCompiler.replay("test/replay", assignment(), context, producer,
				DefaultCollectionFactory::new);
		try (var invocation = plan.open(input, InvocationOwner.forExecution(context))) {
			input.setBinding("inputOnly", VF.createLiteral("mutated"));
			for (int probe = 0; probe < 2; probe++) {
				assertThat(read(invocation.probe(plan.layout().unrestricted()))).singleElement().satisfies(row -> {
					assertThat(row.getValue("inputOnly")).isEqualTo(VF.createLiteral("original"));
					assertThat(row.getValue("producerOnly")).isEqualTo(VF.createLiteral("extra"));
				});
			}
		}
	}

	@Test
	void concurrentCancellationStopsAnInProgressProducerRead() throws Exception {
		var context = new QueryEvaluationContext.Minimal(null);
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		AtomicInteger closes = new AtomicInteger();
		QueryEvaluationStep producer = input -> new LookAheadIteration<>() {
			@Override
			protected BindingSet getNextElement() {
				entered.countDown();
				await(release);
				return EMPTY;
			}

			@Override
			protected boolean forwardCancellation() {
				release.countDown();
				return true;
			}

			@Override
			protected void handleClose() {
				closes.incrementAndGet();
			}
		};
		var plan = RestrictionCompiler.replay("test/replay", assignment(), context, producer,
				DefaultCollectionFactory::new);
		try (var invocation = plan.open(EMPTY, InvocationOwner.forExecution(context));
				var rows = invocation.probe(plan.layout().unrestricted());
				var executor = Executors.newSingleThreadExecutor()) {
			var result = executor.submit(rows::hasNext);
			await(entered);
			assertThat(invocation.requestCancellation()).isTrue();
			assertThat(result.get(10, TimeUnit.SECONDS)).isFalse();
		}
		assertThat(closes).hasValue(1);
	}

	private static void await(CountDownLatch latch) {
		try {
			assertThat(latch.await(10, TimeUnit.SECONDS)).isTrue();
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new AssertionError(interrupted);
		}
	}

	private static BindingSetAssignment assignment() {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of("key", "allocation"));
		values.setBindingSets(List.of());
		return values;
	}

	private static List<BindingSet> read(CloseableIteration<BindingSet> rows) {
		try (rows) {
			return QueryResults.asList(rows);
		}
	}
